// openai/compat/sse_wrapper.go - defer byte-level delimiters to encoder
func (w *wrapper) sendToken(token string) {
  // previously injected "data: {"partial":...}" lines here; now we build logical event and let encoder emit bytes
  event := buildTokenEvent(token)
  w.encoder.emitEvent("token", event)
}

